import{_ as l,o as t,c as i,a2 as n}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"10.3 照明线路的安装","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-3-zhao-ming-xian-lu-de-an-zhuang.md","filePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-3-zhao-ming-xian-lu-de-an-zhuang.md","lastUpdated":1793096070000}'),o={name:"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-3-zhao-ming-xian-lu-de-an-zhuang.md"};function s(e,a,r,g,h,c){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="_10-3-照明线路的安装" tabindex="-1">10.3 照明线路的安装 <a class="header-anchor" href="#_10-3-照明线路的安装" aria-label="Permalink to &quot;10.3 照明线路的安装&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>照明线路的安装有一个&quot;铁律&quot;:<strong>开关必须串在火线上</strong>。这一节讲清照明电路怎么接线、开关和灯具怎么装,这是实操考核的常考点。</p><h2 id="一、照明电路的基本接线" tabindex="-1">一、照明电路的基本接线 <a class="header-anchor" href="#一、照明电路的基本接线" aria-label="Permalink to &quot;一、照明电路的基本接线&quot;">​</a></h2><p>一个最简单的照明回路:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>火线(L)──开关──灯──中性线(N)</span></span>
<span class="line"><span>         └──► 开关串在火线回路中</span></span></code></pre></div><p><strong>基本原则(必背)</strong>:</p><ul><li><strong>开关必须接在火线(L)上</strong>,切断火线才能安全断电;</li><li><strong>中性线(N)直接到灯头</strong>,不经过开关;</li><li>若开关接在零线上,关灯后灯头仍带电(火线直接到灯),换灯泡会触电——这是<strong>严禁</strong>的。</li></ul><blockquote><p>⚠️ 判断题高频:开关应串接在**相线(火线)**上,不能串接在零线上。把开关接零线是危险错误。</p></blockquote><h2 id="二、螺口灯头的接线-必考" tabindex="-1">二、螺口灯头的接线(必考) <a class="header-anchor" href="#二、螺口灯头的接线-必考" aria-label="Permalink to &quot;二、螺口灯头的接线(必考)&quot;">​</a></h2><p>螺口灯头有两个接线点:<strong>中心触点</strong>和<strong>螺纹(外圈)</strong>:</p><ul><li><strong>火线(L)接中心触点</strong>;</li><li><strong>零线(N)接螺纹外圈</strong>。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     中心触点 ← 接火线(L)</span></span>
<span class="line"><span>   螺纹外圈 ← 接零线(N)</span></span></code></pre></div><p>原因:换灯泡时最容易碰到<strong>螺纹外圈</strong>,接零线即使碰到也不易触电;中心触点接火线,但平时被灯泡盖住。</p><blockquote><p>⚠️ 判断题高频:<strong>螺口灯头,相线接中心触点,零线接螺纹</strong>——反了会增大触电危险。</p></blockquote><h2 id="三、灯具的安装要求" tabindex="-1">三、灯具的安装要求 <a class="header-anchor" href="#三、灯具的安装要求" aria-label="Permalink to &quot;三、灯具的安装要求&quot;">​</a></h2><ul><li>灯具<strong>吊装/安装高度</strong>按规范:吊灯垂线不低于一定高度,一般场所灯具离地不低于 <strong>2 米</strong>左右(防人碰到);</li><li>灯具应固定牢固,吊线承重合格;</li><li>潮湿场所(浴室)要用<strong>防潮灯具</strong>,开关装在干燥处;</li><li>灯具金属外壳(非双重绝缘)要<strong>接地(PE)</strong>。</li></ul><h2 id="四、开关、插座的安装" tabindex="-1">四、开关、插座的安装 <a class="header-anchor" href="#四、开关、插座的安装" aria-label="Permalink to &quot;四、开关、插座的安装&quot;">​</a></h2><h3 id="开关" tabindex="-1">开关 <a class="header-anchor" href="#开关" aria-label="Permalink to &quot;开关&quot;">​</a></h3><ul><li>安装高度一般约 <strong>1.3~1.4 米</strong>(距地),操作方便;</li><li>多个开关并列时,开闭方向一致;</li><li>厨房、卫生间潮湿处,开关尽量装在门外或干燥处。</li></ul><h3 id="插座" tabindex="-1">插座 <a class="header-anchor" href="#插座" aria-label="Permalink to &quot;插座&quot;">​</a></h3><ul><li>普通插座安装高度:一般距地 <strong>0.3 米</strong>(家用)或按规范;</li><li>卫生间、厨房等潮湿场所要用<strong>防溅型</strong>插座;</li><li>插座接线:<strong>左零右火上接地</strong>?——不,我国规范是<strong>左零(N)右火(L)上接地(PE)</strong>;</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>插座(面对插座): 左孔─N(零线)  右孔─L(火线)  上孔─PE(接地)</span></span></code></pre></div><blockquote><p>⚠️ 判断题高频:单相两孔/三孔插座,面对插座<strong>左零右火</strong>,三孔插座<strong>上孔接地</strong>。</p></blockquote><h2 id="五、照明配电要求" tabindex="-1">五、照明配电要求 <a class="header-anchor" href="#五、照明配电要求" aria-label="Permalink to &quot;五、照明配电要求&quot;">​</a></h2><ul><li>照明回路一般单独配电,不用太大截面的导线;</li><li>每回路要有<strong>短路和过载保护</strong>(熔断器/断路器);</li><li>移动电器、插座的回路装<strong>漏电保护器</strong>。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ <strong>开关接火线</strong>,零线直接到灯头。</li><li>✅ 螺口灯头:火线接<strong>中心触点</strong>,零线接<strong>螺纹</strong>。</li><li>✅ 插座:左零右火,上面接地。</li><li>✅ 灯具距地一般不低于 2 米。</li><li>⚠️ 易混点:开关接零线(错!)vs 开关接火线(对),这是安全底线。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>照明接线的核心是&quot;开关断火线&quot;。</li><li>螺口灯头、插座都有规定的接线顺序。</li><li>灯具高度、潮湿防护、接地都要按规范。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)照明开关必须串接在火线上,不允许串接在零线上。( )</li><li>(单选)螺口灯头接线,正确的是()。 A. 火线接螺纹,零线接中心触点　B. 火线接中心触点,零线接螺纹 C. 两线随便接　D. 都接零线</li><li>(判断)面对插座,三孔插座的上孔接保护接地线(PE)。( )</li><li>(单选)一般家用单相插座接线,正确的是()。 A. 左火右零　B. 左零右火　C. 上零下火　D. 左右都接火</li><li>(判断)潮湿场所(如浴室)应使用防潮灯具,开关安装在干燥处。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。开关必须接火线,接零线是危险错误。</li><li><strong>B</strong>。火线接中心触点,零线接螺纹。</li><li><strong>√</strong>。三孔插座上孔(中间)接地线 PE。</li><li><strong>B</strong>。面对插座左零右火。</li><li><strong>√</strong>。潮湿场所要防潮、防溅。</li></ol></details>`,33)])])}const p=l(o,[["render",s]]);export{u as __pageData,p as default};
